              "id": "b4",
              "label": "已完成",
              "text": "破损书目登记。",
              "sourceIds": ["s1"]
            },
            {
              "id": "b5",
              "label": "仍需排队",
              "text": "修复工作按损坏程度排队；登记完成不等于修复完成。",
              "sourceIds": ["s1"]
            }
          ]
        }
      ]
    },
